use super::*;
use photocraft_engine::{doc::{PixelFormat, SampleType}, DocState};

fn run(engine:&mut Session,command:&str,params:Value)->Result<Value,String>{super::super::execute_view_command(engine,command,params)}
fn surface_mut(doc:&mut Document,target:Target)->&mut Surface{match target{Target::Mask(id)=>&mut doc.layer_mut(id).unwrap().mask.as_mut().unwrap().surface,Target::Alpha(index)=>&mut doc.channels[index].surface,Target::QuickMask=>&mut doc.quick_mask.as_mut().unwrap().surface}}
fn twin(engine:&Session)->Session{let mut copy=Session::new();copy.add_document((*engine.active().unwrap().doc).clone(),None);*copy.active_mut().unwrap()=engine.active().unwrap().clone();copy.tools=engine.tools.clone();copy.presets=engine.presets.clone();copy.patterns=engine.patterns.clone();copy.journal=engine.journal.clone();copy.edit_state=engine.edit_state.clone();copy}

fn fixture(depth:u32,route:&str,explicit:bool)->(Session,Target,Value){
    let mut engine=Session::new();engine.execute("file.new",json!({"width":24,"height":20,"depth":depth,"background":"#4080b0"})).unwrap();let layer=engine.active().unwrap().active_layer.unwrap();
    engine.execute("layer.layerMask.revealAll",json!({})).unwrap();engine.execute("channel.new",json!({"name":"Coverage"})).unwrap();
    let target=match route{"mask"=>Target::Mask(layer),"alpha"=>Target::Alpha(0),_=>{engine.execute("select.editInQuickMaskMode",json!({})).unwrap();Target::QuickMask}};
    engine.edit("Fill and patch coverage",|doc,_|{let format=PixelFormat{sample:doc.depth,..PixelFormat::GRAY8};let mut surface=Surface::with_default(format,&[1.0]);let values:Vec<_>=(0..480).map(|index|0.05+((index*13+index/24*7)%17)as f32/20.0).collect();surface.write_region(Rect::from_xywh(0,0,24,20),&values);surface.write_pixel(-2,3,&[0.4]);*surface_mut(doc,target)=surface;let mut selection=Surface::new(PixelFormat::GRAY8);selection.fill_rect(Rect::from_xywh(3,3,18,14),&[0.7]);selection.write_pixel(8,8,&[0.3]);doc.selection=Some(selection);Ok(())}).unwrap();
    engine.execute("channel.target",json!({"channel":"composite"})).unwrap();if !explicit{match target{Target::Mask(_)=>{engine.execute("view.layerMask",json!({"mode":"gray"})).unwrap();},Target::Alpha(index)=>{engine.execute("channel.target",json!({"channel":index})).unwrap();},Target::QuickMask=>{}}}
    engine.tools.foreground=[0.9,0.9,0.9,1.0];engine.tools.background=[0.1,0.1,0.1,1.0];let mut params=json!({"x":8,"y":8,"tolerance":255,"contiguous":false,"color":"#d0d0d0","opacity":65,"from":[3,3],"to":[20,15],"colors":["#101010","#eeeeee"],"dither":false});if explicit{params["target"]=encoded(target);}(engine,target,params)
}
fn unchanged(source:&DocState,current:&DocState,target:Target){let mut restored=(*current.doc).clone();*surface_mut(&mut restored,target)=plane(&source.doc,target).unwrap().clone();assert_eq!(&restored,source.doc.as_ref());assert_eq!(current.channel_view,source.channel_view);assert_eq!(current.active_layer,source.active_layer);assert_eq!(current.selected_layers,source.selected_layers);}
fn endpoints(engine:&Session,source:&DocState,target:Target){let bounds=Rect::from_xywh(-3,-2,30,26);let original=plane(&source.doc,target).unwrap().read_region(bounds);let edited=engine.active().unwrap().doc.clone();let after=plane(&edited,target).unwrap().read_region(bounds);assert_ne!(original,after);for opacity in [0.0,50.0,100.0]{let mut faded=twin(engine);run(&mut faded,"edit.fade",json!({"opacity":opacity,"mode":"normal"})).unwrap();let current=faded.active().unwrap();let surface=plane(&current.doc,target).unwrap();let tolerance=match surface.format().sample{SampleType::U8=>1.01/255.0,SampleType::U16=>1.01/65535.0,SampleType::F32=>0.000001};for((before,after),actual)in original.iter().zip(&after).zip(surface.read_region(bounds)){assert!((actual-(before+(after-before)*(opacity as f32/100.0))).abs()<=tolerance);}unchanged(source,current,target);run(&mut faded,"edit.undo",json!({})).unwrap();assert_eq!(faded.active().unwrap().doc,edited);run(&mut faded,"edit.undo",json!({})).unwrap();assert_eq!(faded.active().unwrap().doc,source.doc);run(&mut faded,"edit.redo",json!({})).unwrap();assert_eq!(faded.active().unwrap().doc,edited);}}

#[test]
fn native_fill_routes_preserve_pixels_and_fade_actual_coverage_at_three_depths(){
    for depth in [8,16,32]{for route in ["mask","alpha","quickMask"]{for explicit in [false,true]{for command in FILL_FADE_COMMANDS{
        let(mut engine,target,params)=fixture(depth,route,explicit);let source=engine.active().unwrap().clone();let journal=engine.journal.len();let mut native=twin(&engine);let expected=native.execute(command,params.clone()).unwrap();assert_eq!(run(&mut engine,command,params).unwrap(),expected);assert_eq!(engine.active().unwrap().doc,native.active().unwrap().doc);assert_eq!(engine.active().unwrap().history.entries(),native.active().unwrap().history.entries());assert_eq!(engine.active().unwrap().coalesce,native.active().unwrap().coalesce);assert_eq!(engine.journal.len(),journal+1);assert!(can_fade(&engine)||engine.is_enabled("edit.fade"));endpoints(&engine,&source,target);
    }}}}
}

#[test]
fn explicit_patch_coverage_fades_both_modes_and_implicit_patch_remains_native_pixels(){
    for depth in [8,16,32]{for route in ["mask","alpha","quickMask"]{for mode in ["source","destination"]{let(mut engine,target,_)=fixture(depth,route,true);let params=json!({"target":encoded(target),"offset":[2,0],"mode":mode});let source=engine.active().unwrap().clone();let mut native=twin(&engine);native.execute("paint.patch",params.clone()).unwrap();run(&mut engine,"paint.patch",params).unwrap();assert_eq!(engine.active().unwrap().doc,native.active().unwrap().doc);endpoints(&engine,&source,target);}}}
    for route in ["alpha","quickMask"]{let(mut engine,target,_)=fixture(16,route,false);let source=engine.active().unwrap().clone();let mut native=twin(&engine);let params=json!({"offset":[2,0]});native.execute("paint.patch",params.clone()).unwrap();run(&mut engine,"paint.patch",params).unwrap();assert_eq!(engine.active().unwrap().doc,native.active().unwrap().doc);assert_eq!(engine.edit_state.fade,native.edit_state.fade);assert_eq!(engine.journal,native.journal);assert_eq!(plane(&engine.active().unwrap().doc,target).unwrap(),plane(&source.doc,target).unwrap());assert!(!can_fade(&engine));}
}

#[test]
fn mixed_fill_groups_restore_gesture_start_and_alias_masks_keep_first_label(){
    for route in ["mask","alpha","quickMask"]{for explicit in [false,true]{let(mut engine,target,mut params)=fixture(16,route,explicit);params["coalesce"]=json!("fill-gesture");let source=engine.active().unwrap().clone();run(&mut engine,"edit.fillForeground",params.clone()).unwrap();let label=engine.active().unwrap().history.undo_label().unwrap().to_owned();run(&mut engine,"paint.gradient",params).unwrap();assert_eq!(engine.active().unwrap().history.past_len(),source.history.past_len()+1);assert_eq!(engine.active().unwrap().history.undo_label(),Some(label.as_str()));let result=run(&mut engine,"edit.fade",json!({"opacity":0})).unwrap();assert_eq!(result["faded"],label);assert_eq!(plane(&engine.active().unwrap().doc,target).unwrap().read_region(source.doc.bounds()),plane(&source.doc,target).unwrap().read_region(source.doc.bounds()));}}
}

#[test]
fn fill_no_revision_errors_and_explicit_pixels_preserve_native_semantics(){
    for command in FILL_FADE_COMMANDS{let(mut engine,target,mut params)=fixture(8,"alpha",false);params["target"]=json!("pixels");let original=plane(&engine.active().unwrap().doc,target).unwrap().clone();let mut native=twin(&engine);native.execute(command,params.clone()).unwrap();run(&mut engine,command,params).unwrap();assert_eq!(engine.active().unwrap().doc,native.active().unwrap().doc);if !FILL_ALIASES.contains(&command){assert_eq!(engine.edit_state.fade,native.edit_state.fade);}else{assert!(engine.is_enabled("edit.fade"));assert!(!engine.edit_state.fade.as_ref().unwrap().mask);}assert_eq!(plane(&engine.active().unwrap().doc,target).unwrap(),&original);assert!(!can_fade(&engine));}
    let(mut engine,_,params)=fixture(16,"alpha",true);run(&mut engine,"edit.fill",params.clone()).unwrap();engine.edit("Outside selection",|doc,_|{let mut selection=Surface::new(photocraft_engine::doc::PixelFormat::GRAY8);selection.fill_rect(Rect::from_xywh(40,40,3,3),&[1.0]);doc.selection=Some(selection);Ok(())}).unwrap();let source=engine.active().unwrap().clone();let journal=engine.journal.len();run(&mut engine,"edit.fill",params.clone()).unwrap();assert!(std::sync::Arc::ptr_eq(&source.doc,&engine.active().unwrap().doc));assert_eq!(engine.active().unwrap().revision,source.revision);assert_eq!(engine.journal.len(),journal+1);assert!(!can_fade(&engine));assert!(!engine.is_enabled("edit.fade"));
    let(mut engine,_,_)=fixture(16,"alpha",true);
    for invalid in [json!({"target":{"channel":0},"contents":"contentAware"}),json!({"target":{"channel":999}}),json!({"target":{"channel":0},"opacity":"bad"}),json!({"target":{"channel":0},"mode":"missing"}),json!({"target":{"channel":0},"preserveTransparency":"bad"})]{let before=engine.active().unwrap().clone();let journal=engine.journal.clone();assert!(run(&mut engine,"edit.fill",invalid).is_err());assert!(std::sync::Arc::ptr_eq(&before.doc,&engine.active().unwrap().doc));assert_eq!(engine.journal,journal);}
    let(mut engine,_,_)=fixture(8,"alpha",false);run(&mut engine,"edit.fill",Value::Null).unwrap();assert!(can_fade(&engine));
}

#[test]
fn inactive_explicit_mask_fill_and_patch_fade_the_actual_native_target(){
    for command in ["edit.fill","paint.patch"]{let(mut engine,target,mut params)=fixture(16,"mask",true);let Target::Mask(layer)=target else{unreachable!()};engine.execute("layer.new.layer",json!({"name":"Unrelated active layer"})).unwrap();params["layer"]=json!(layer.0);if command=="paint.patch"{params["offset"]=json!([2,0]);}let source=engine.active().unwrap().clone();let mut native=twin(&engine);native.execute(command,params.clone()).unwrap();run(&mut engine,command,params).unwrap();assert_eq!(engine.active().unwrap().doc,native.active().unwrap().doc);assert_eq!(engine.active().unwrap().active_layer,source.active_layer);assert_eq!(engine.edit_state.fade.as_ref().unwrap().layer,layer);assert!(engine.edit_state.fade.as_ref().unwrap().mask);endpoints(&engine,&source,target);}
    for command in ["paint.bucket","paint.gradient"]{let(mut engine,target,mut params)=fixture(16,"mask",true);let Target::Mask(layer)=target else{unreachable!()};engine.execute("layer.new.layer",json!({"name":"Actual active mask"})).unwrap();engine.execute("layer.layerMask.revealAll",json!({})).unwrap();params["layer"]=json!(layer.0);let mut native=twin(&engine);native.execute(command,params.clone()).unwrap();run(&mut engine,command,params).unwrap();assert_eq!(engine.active().unwrap().doc,native.active().unwrap().doc);assert_eq!(engine.edit_state.fade,native.edit_state.fade);assert_eq!(engine.edit_state.fade.as_ref().unwrap().layer,engine.active().unwrap().active_layer.unwrap());}
}
